```typescript
// ✅ React 18: optimistic update using temporary state
function FileList({ files }: { files: PdfFile[] }) {
  const [optimisticFiles, setOptimisticFiles] = useState(files);

  async function handleAdd(file: File) {
    const tempFile = { id: 'temp', name: file.name, pending: true };
    setOptimisticFiles(prev => [...prev, tempFile]);
    try {
      await window.api.addFile(file);
    } catch {
      setOptimisticFiles(prev => prev.filter(f => f.id !== 'temp'));
    }
  }

  return (
    <div>
      {optimisticFiles.map(f => (
        <FileCard key={f.id || 'temp'} file={f} opacity={f.pending ? 0.5 : 1} />
      ))}
    </div>
  );
}
